sys_script.script:
(function executeRule(current, previous) {

    // This after-update BR fires when an OTP code was successfully
    // validated by the before-update BR (which didn't abort).
    // It sets otp_verified=true and clears otp_code via a separate
    // GlideRecord.update() to ensure persistence in all contexts.

    // Only act if otp_verified is still false and an otp_code was submitted
    if (current.getValue('otp_verified') == '1') {
        return; // already verified, nothing to do
    }

    var otpCode = current.getValue('otp_code');
    if (!otpCode) {
        return; // no OTP code submitted, nothing to do
    }

    // If we're here, the before-update BR validated the code successfully
    // (otherwise it would have aborted and this after-update BR wouldn't fire).
    // Now set otp_verified=true and clear otp_code using a direct DB update.
    var gr = new GlideRecord('x_1919710_refurt_0_service_log');
    if (gr.get(current.getUniqueValue())) {
        gr.setValue('otp_verified', 'true');
        gr.setValue('otp_code', '');
        gr.update();
    }

})(current, previous);
